     prd) validate_prd ;;
     sdd) validate_sdd ;;
@@ -1203,6 +1335,7 @@ case "$TYPE" in
     decisions) validate_decisions ;;
     map) validate_map ;;
     spike) validate_spike ;;
+    glossary) validate_glossary ;;
 esac

